const stoneColor = params.stoneColor;
const roofColor = params.roofColor;
const R = 0.82;
const wallH = 0.72;
const wallT = 0.22;
const stone = { preset: 'stone', roughness: 0.95, flatShading: true };
const mortar = { preset: 'stone', color: api.mix(stoneColor, '#343536', 0.48), roughness: 1 };
const wood = { preset: 'wood', color: '#69452c', roughness: 0.86 };
const darkWood = { preset: 'wood', color: '#3b271b', roughness: 0.9 };
const metal = { preset: 'metal', color: '#34383a', metalness: 0.75, roughness: 0.42 };
const water = { preset: 'water', color: '#397f91', opacity: 0.76, roughness: 0.12, emissive: '#1b5968', emissiveIntensity: 0.16 };
const wallProfile = [[R - wallT, 0], [R, 0], [R, wallH], [R - wallT, wallH], [R - wallT, 0]];
const wall = api.lathe(wallProfile, 24);
wall.vertexColor((x, y, z) => api.mix(stoneColor, '#555953', 0.12 + 0.11 * api.noise3(x * 5, y * 7, z * 5)));
api.add(wall, stone);
api.add(api.torus(R + 0.015, 0.055).rotate(90, 0, 0).translate(0, 0.08, 0), mortar);
api.add(api.torus(R + 0.015, 0.055).rotate(90, 0, 0).translate(0, 0.31, 0), mortar);
api.add(api.torus(R + 0.015, 0.055).rotate(90, 0, 0).translate(0, 0.54, 0), mortar);
for (let course = 0; course < 3; course++) {
  const count = 14;
  const y = 0.155 + course * 0.23;
  const phase = (course % 2) * Math.PI / count;
  for (let i = 0; i < count; i++) {
    const a = phase + i * Math.PI * 2 / count;
    const block = api.box(0.31, 0.18, 0.15).rotate(0, -a * 180 / Math.PI, 0).translate(Math.cos(a) * (R - 0.005), y, Math.sin(a) * (R - 0.005));
    block.vertexColor(() => api.mix(stoneColor, '#4e514d', 0.06 + 0.18 * api.rng()));
    api.add(block, stone);
  }
}
const coping = api.lathe([[R - wallT - 0.06, wallH], [R + 0.09, wallH], [R + 0.09, wallH + 0.15], [R - wallT - 0.06, wallH + 0.15], [R - wallT - 0.06, wallH]], 24);
coping.vertexColor((x, y, z) => api.mix(stoneColor, '#d0ccc0', 0.12 + 0.08 * api.noise3(x * 4, y * 4, z * 4)));
api.add(coping, stone);
api.add(api.cylinder(R - wallT - 0.075, R - wallT - 0.075, 0.035, 24).translate(0, 0.61, 0), water);
const postX = 0.91;
for (let side = -1; side <= 1; side += 2) {
  api.add(api.box(0.18, 1.75, 0.18).translate(side * postX, 1.18, 0), wood);
  api.add(api.box(0.25, 0.12, 0.25).translate(side * postX, 0.34, 0), darkWood);
  api.add(api.box(0.28, 0.12, 0.28).translate(side * postX, 2.02, 0), darkWood);
}
api.add(api.box(2.18, 0.16, 0.18).translate(0, 1.97, 0), wood);
const slope = 35;
api.add(api.box(1.18, 0.095, 1.72).rotate(0, 0, slope).translate(-0.48, 2.32, 0), { preset: 'wood', color: roofColor, roughness: 0.88 });
api.add(api.box(1.18, 0.095, 1.72).rotate(0, 0, -slope).translate(0.48, 2.32, 0), { preset: 'wood', color: roofColor, roughness: 0.88 });
api.add(api.box(0.12, 0.12, 1.8).translate(0, 2.65, 0), darkWood);
for (let j = -3; j <= 3; j++) {
  const z = j * 0.235;
  api.add(api.box(1.16, 0.028, 0.035).rotate(0, 0, slope).translate(-0.48, 2.335, z), darkWood);
  api.add(api.box(1.16, 0.028, 0.035).rotate(0, 0, -slope).translate(0.48, 2.335, z), darkWood);
}
api.add(api.cylinder(0.075, 0.075, 2.05, 12).rotate(0, 0, 90).translate(0, 1.38, 0), darkWood);
api.add(api.cylinder(0.13, 0.13, 0.12, 12).rotate(0, 0, 90).translate(-0.98, 1.38, 0), metal);
api.add(api.tube([[-1.04, 1.38, 0], [-1.22, 1.38, 0], [-1.22, 1.18, 0]], 0.035, 8), metal);
api.add(api.sphere(0.075, 1).translate(-1.22, 1.12, 0), darkWood);
api.add(api.tube([[0, 1.38, 0], [0, 0.74, 0]], 0.018, 6), { preset: 'fabric', color: '#b59a70', roughness: 1 });
const bucketY = 0.57;
api.add(api.cylinder(0.15, 0.19, 0.25, 12).translate(0, bucketY, 0), { preset: 'wood', color: '#7a5333', roughness: 0.9 });
api.add(api.torus(0.19, 0.018).rotate(90, 0, 0).translate(0, bucketY - 0.115, 0), metal);
api.add(api.torus(0.15, 0.018).rotate(90, 0, 0).translate(0, bucketY + 0.115, 0), metal);
api.add(api.torus(0.17, 0.018).translate(0, bucketY + 0.19, 0), metal);
const colN = 12;
for (let i = 0; i < colN; i++) {
  const a = i * Math.PI * 2 / colN;
  api.collider({ kind: 'box', halfExtents: [0.205, 0.435, wallT * 0.55], offset: [Math.cos(a) * (R - wallT * 0.45), 0.435, Math.sin(a) * (R - wallT * 0.45)], rotation: [0, -a * 180 / Math.PI, 0] });
}
api.collider({ kind: 'box', halfExtents: [0.09, 0.875, 0.09], offset: [-postX, 1.18, 0] });
api.collider({ kind: 'box', halfExtents: [0.09, 0.875, 0.09], offset: [postX, 1.18, 0] });
return api.build();
